def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0

    alive_opps = []
    prev_bids = []
    desperate_opps = 0
    rich_opps = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                desperate_opps += 1
            if opp.get('budget', 0) >= DAILY_SALARY * 3:
                rich_opps += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive_opps:
        return min(budget, 20)

    competitors = len(alive_opps) + 1
    units = supply / float(WATER_REQ)
    scarcity = competitors - units

    critical = hp <= 2 or no_water >= 1
    very_critical = hp <= 1 or no_water >= 2

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 0
        avg_prev = 0

    if very_critical:
        bid = DAILY_SALARY * 0.96
    elif critical:
        if highest_prev > 0:
            bid = max(DAILY_SALARY * 0.82, highest_prev + 2)
        else:
            bid = DAILY_SALARY * 0.84
    else:
        if scarcity <= 0:
            bid = DAILY_SALARY * 0.22
        elif scarcity < 1:
            bid = DAILY_SALARY * 0.42
        else:
            bid = DAILY_SALARY * 0.62

        if highest_prev >= DAILY_SALARY * 0.85:
            bid = min(bid, DAILY_SALARY * 0.35)
        elif highest_prev >= DAILY_SALARY * 0.55:
            bid = max(bid, min(DAILY_SALARY * 0.68, highest_prev + 1.5))
        elif highest_prev > 0:
            bid = max(bid, highest_prev + 1)

        if desperate_opps >= max(1, len(alive_opps) // 2):
            bid += 6
        if rich_opps >= max(1, len(alive_opps) // 2):
            bid += 4
        if day >= 8:
            bid += 5

    reserve_floor = 0
    if day <= 3 and not critical:
        reserve_floor = DAILY_SALARY * 1.2
    elif day <= 6 and not critical:
        reserve_floor = DAILY_SALARY * 0.6

    max_affordable = budget
    if budget > reserve_floor:
        max_affordable = budget - reserve_floor
    if critical:
        max_affordable = budget

    if max_affordable < 0:
        max_affordable = 0

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0, bid)

    if critical and bid < DAILY_SALARY * 0.75:
        bid = min(budget, DAILY_SALARY * 0.75)

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no opponents, bid conservatively
    if not alive_opps:
        return min(float(my_status['budget']), DAILY_SALARY * 0.4)

    # Read yesterday's bids
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Pressure estimate from yesterday
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / float(len(yesterday_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # Urgency based on our hp/no-water streak
    my_hp = float(my_status['hp'])
    no_water_days = int(my_status['no_water_days'])
    budget = float(my_status['budget'])

    urgency = 0.0
    if my_hp <= 2.0:
        urgency += 0.35
    elif my_hp <= 4.0:
        urgency += 0.2
    if no_water_days >= 2:
        urgency += 0.25
    elif no_water_days == 1:
        urgency += 0.12

    # Supply factor: lower supply => higher need to secure water
    supply_factor = 0.0
    if supply <= float(MIN_SUPPLY):
        supply_factor = 0.35
    elif supply <= (float(MIN_SUPPLY) + float(MAX_SUPPLY)) / 2.0:
        supply_factor = 0.2
    else:
        supply_factor = 0.1

    # Strategy: react to opponent aggressiveness
    # If opponents were bidding near/above our salary, they are likely fighting for scarce water.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Bid enough to not be shut out, but avoid overpaying.
        target = DAILY_SALARY * (0.25 + urgency + supply_factor)
        # Also hedge against their likely continued high bids by adding a small increment.
        target = max(target, highest_prev_bid * 0.75)
    else:
        # Opponents were calmer: underbid slightly relative to their average/highest.
        # Add urgency/supply to avoid missing water.
        base = max(DAILY_SALARY * (0.45 + urgency + supply_factor), avg_prev_bid * 0.9)
        # If they bid something non-trivial yesterday, try to be just under their top to save budget.
        if highest_prev_bid > 0.0:
            target = min(base, highest_prev_bid + DAILY_SALARY * 0.05)
        else:
            target = base

    # Convert to final bid with budget cap
    if budget <= 0.0:
        return 0.0

    # Ensure bid is within [0, budget] and not absurdly high
    bid = min(budget, max(0.0, float(target)))

    # If we are extremely low hp, push harder
    if my_hp <= 1.0:
        bid = min(budget, max(bid, DAILY_SALARY * 0.9))

    # Slight day-based modulation (early days more conservative)
    if day <= 3:
        bid *= 0.95

    return float(bid)
